{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Trametinib, a pyrido-pyrimidine-dione with an N-aryl substituent and an aminoaryl group, has a measured absolute oral bioavailability of 72.3% (90% CI 50.0–104.6%) in patients with solid tumours, determined by oral tablet versus i.v. microtracer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Niraparib, an oral oncology drug with a fused heteroaromatic core and a basic nitrogen heterocycle, has an absolute oral bioavailability of 72.7% (90% CI 61.69–83.40) in patients, measured against IV 14C-niraparib.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam, a structurally related pyrido-pyrimidine-type compound, has high oral bioavailability due to complete absorption and negligible first-pass extraction in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, an oral kinase inhibitor containing an aminopyrimidine and N-methylpiperazine, has a mean absolute bioavailability of 98% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, a small-molecule kinase inhibitor with a heteroaromatic amine and saturated nitrogen heterocycle, has an estimated absolute bioavailability of 75% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fused pyrido-pyrimidine-dione with an N-aryl piperazine and cyclopentyl group, closely resembling trametinib and niraparib, both of which have absolute human oral bioavailability values around 72–73%. Additional analogues with similar heteroaromatic amine/piperazine features (imatinib, brepocitinib, risdiplam) also show high F. No transferable evidence supports low bioavailability; therefore the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The query's specific solubility, permeability, and first-pass metabolism are not directly measured in the available records.",
    "Most supporting analogues are oncology kinase inhibitors; extrapolation to this exact scaffold relies on structural analogy rather than identical compound data."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C18"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "pyrido-pyrimidine-dione kinase inhibitors"
    },
    {
      "applicability": "high",
      "card_ids": ["C31"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "fused heteroaromatic oral oncology drugs"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "aminopyrimidine-piperazine kinase inhibitors"
    }
  ],
  "revision_action": "initial"
}

